143	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
144	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
145	// entire.io discovers the external checkpoint repo by reading the committed project
146	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
147	// (not just in settings.local.json or uncommitted local changes).
148	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
149	// single pre-push invocation.
150	func printSettingsCommitHint(ctx context.Context, target string) {
151		if !remote.IsURL(target) {
152			return
153		}
154		settingsHintOnce.Do(func() {
155			if isCheckpointRemoteCommitted(ctx) {
156				return
157			}
158			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
159		})
160	}
