162	// printCheckpointsV2MigrationHint nudges users who committed checkpoints_version: 2
163	// but never ran the migration. Partial migrations are not flagged.
164	func printCheckpointsV2MigrationHint(ctx context.Context) {
165		checkpointsV2MigrationHintOnce.Do(func() {
166			if !isCheckpointsVersion2Committed(ctx) {
167				return
168			}
169			if v2MainRefExists(ctx) {
170				return
171			}
172			fmt.Fprintln(os.Stderr, "[entire] Note: .entire/settings.json sets checkpoints_version: 2, but no v2 /main ref was found in this repo.")
173			fmt.Fprintln(os.Stderr, "[entire] Run 'entire migrate --checkpoints v2' to migrate missing checkpoints to v2.")
174		})
175	}
