205	// at HEAD sets checkpoints_version to 2.
206	func isCheckpointsVersion2Committed(ctx context.Context) bool {
207		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
208		output, err := cmd.Output()
209		if err != nil {
210			return false
211		}
212		committed, err := settings.LoadFromBytes(output)
213		if err != nil {
214			return false
215		}
216		return committed.CheckpointsVersion() == 2
217	}
