-func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
-	sort.SliceStable(checkpoints, func(i, j int) bool {
-		left := checkpoints[i].CreatedAt
-		right := checkpoints[j].CreatedAt
-		switch {
-		case left.IsZero() && right.IsZero():
